{
  "hypotheses": [
    {
      "text": "Data‑artifact: XBRL tagging for the us‑gaap Revenues concept was not consistently used by Tesla in filings before FY 2011, so no revenue facts exist for those years.",
      "how_to_test": "SELECT COUNT(*) AS fact_cnt FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE cik = '1318605' AND fiscal_year < 2011;"
    },
    {
      "text": "Real‑world: Tesla generated only minimal or zero revenue before FY 2011 (early Roadster production), and those values were either reported as zero or omitted from the XBRL subset that the pipeline extracts, resulting in an apparent start‑date of 2011.",
      "how_to_test": "SELECT fiscal_year, SUM(value_usd) AS total_rev FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE cik = '1318605' AND fiscal_year < 2011 GROUP BY fiscal_year ORDER BY fiscal_year;"
    },
    {
      "text": "Data‑artifact: Duplicate filings for early years produce period_frame = NULL, and the current view excludes rows where period_frame IS NULL (perhaps via a hidden filter), causing pre‑2011 facts to be dropped.",
      "how_to_test": "SELECT fiscal_year, period_frame, COUNT(*) AS dup_cnt FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE cik = '1318605' AND fiscal_year < 2011 GROUP BY fiscal_year, period_frame ORDER BY fiscal_year;"
    },
    {
      "text": "Real‑world: Tesla was classified as a smaller reporting company before FY 2011 and was not required to submit XBRL‑tagged financials; the SEC only mandated XBRL for larger filers after a certain threshold, so the data source lacks those early filings.",
      "how_to_test": "SELECT fiscal_year, form_type, COUNT(*) AS filing_cnt FROM lightning.metastore.explainwhy.explainwhy_usl.revenue_fact WHERE cik = '1318605' AND fiscal_year < 2011 GROUP BY fiscal_year, form_type ORDER BY fiscal_year, form_type;"
    }
  ]
}
